$(function () {
    if ($(".side-bar").offset() != undefined) {
        let offset_top = parseInt($(".side-bar").offset().top) - 135
        $(".side-bar-container").css('top', offset_top + 'px')
    }

})

function select_nav_tour(element, id) {
    $(`#${id}`).removeClass('unvisible')
    $(element).addClass('selected')
    $(element).siblings().removeClass('selected')
    $(`#${id}`).siblings().addClass('unvisible')
}
$(document).ready(function () {
    $(".hotel-cost").each(function () {
        $(this).text($(this).text().replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,"));
    })
    $(".loc-input").each(function () {
        var hotelid = $(this).val()
        if (hotelid == 'undefined') {
            $(this).closest(".td-hotel").find(".showhotel").removeAttr('href')
        }
    })
})
//<!---------------START JS CONTACT--------------->//

function select_contact(element, id) {
    $(`#${id}`).removeClass('unvisible')
    $(element).addClass('active')
    $(element).siblings().removeClass('active')
    $(`#${id}`).siblings().addClass('unvisible')
}
