function refresh_captcha(element, event) {
    $(element).closest("form").find(".load-captcha").load("/Client_Captcha.bc");
}
/*------------------SUBMIT FORM-----------------------*/
$(".form-content").submit(function (e) {
    var self = $(this);
    self.closest("form").find(".Message-Form").show();
    e.preventDefault();
    $.ajax({
        url: self.attr("action"),
        type: self.attr("method"),
        data: $(self).serialize(),
        success: function (response) {
            self.closest("form").find(".Message-Form").hide();
            self.closest("form").find(".Message-Form").empty().show().html(response);
        },
    });
});



const toggleCount = (element, type, limit, passenger) => {
    try {
        let currentCount = parseInt(element.closest("li").querySelector(".count__container").textContent);
        type == 'plus' ? currentCount++ : currentCount--;
        if (currentCount < limit) return false;;
        element.closest("li").querySelector(".count__container").textContent = currentCount;
        document.querySelector(".booking-form").querySelector(`.${passenger}-count`).querySelector("input").value = currentCount;
    } catch (err) {
        console.error('toggleCount=' + err.lineNumber + ',' + err.message);
    }
}

const onrenderedSchemaTourBookingForm = async (args) => {
    try {
        let index = 0;
        document.querySelector(".booking-form").querySelector(".schema-content").querySelectorAll(".hidden").forEach(e=>{
            document.querySelector(".booking-form").querySelector(".passenger__form__container").querySelectorAll("li")[index].querySelector(".question__container").textContent = e.querySelector("span").textContent
            index++;
        })
        document.querySelector(".booking-form").querySelector(".adult-count").querySelector("input").value = document.querySelector(".booking-form").querySelector(".adult__count__container").textContent;
        document.querySelector(".booking-form").querySelector(".child-count").querySelector("input").value = document.querySelector(".booking-form").querySelector(".child__count__container").textContent;
        document.querySelector(".booking-form").querySelector(".infant-count").querySelector("input").value = document.querySelector(".booking-form").querySelector(".infant__count__container").textContent;
    } catch (err) {
        console.error('onrenderedSchemaTourBookingForm=' + err.lineNumber + ',' + err.message);
    }
};
const callbackSourceTourBookingForm = async (args) => {
    try {
        document.querySelector(".booking-form").querySelector(".Loading_Form").classList.remove("unvisible");
        $bc.setSource("db.tourBookingForm", {
            value: JSON.stringify(args.source?.rows[0]),
            captcha: document.querySelector(".booking-form").querySelector("input[name='captcha']").value,
            captchaid: document.querySelector(".booking-form").querySelector("input[name='captchaid']").value,
            run: true
        });
    } catch (err) {
        console.error('callbackSourceTourBookingForm=' + err.lineNumber + ',' + err.message);
    }
};
const OnProcessedTourBookingForm = async (args) => {
    try {
        var response = args.response;
        var json = await response.json();
        var errorid = json.errorid;
        document.querySelector(".booking-form").querySelector(".Loading_Form").classList.add("unvisible");
        if (errorid == "6") {
            document.querySelector(".booking-form").querySelector(".Message-Form").innerHTML = "Your request has been successfully registered";
        } else {
            document.querySelector(".booking-form").querySelector(".Message-Form").innerHTML = "An error occurred, please try again";
        }
        setTimeout(function () {
            document.querySelector(".booking-form").querySelector(".Message-Form").innerHTML = "";
            setTimeout(function () {
                document.querySelector(".booking-form").classList.add('hidden');
            }, 500);
        }, 1000);
    } catch (err) {
        console.error('OnProcessedTourBookingForm=' + err.lineNumber + ',' + err.message);
    }
}
const renderCaptchaCode = async (element, event) => {
    try {
        fetch(`/tour/captcha`, {
            method: `get`,
        }).then(response => response.text()).then(text => {
            element.closest(".booking-form").querySelector(".captcha__content").innerHTML = text;
        }).catch(error => console.error(error))
    } catch (err) {
        console.error('renderCaptchaCode=' + err.lineNumber + ',' + err.message);
    }
}

